class Solution {public:vector<int>solve(int n,vector<vector<int>>edges){vector<vector<pair<int,int>>>a(n);for(int id=0;id<(int)edges.size();id++){a[edges[id][0]].push_back({edges[id][1],id});a[edges[id][1]].push_back({edges[id][0],id});}vector<int>time(n,-1),low(n),out;int clock=0;function<void(int,int)>dfs=[&](int u,int parent){time[u]=low[u]=clock++;for(auto [v,id]:a[u])if(id!=parent){if(time[v]<0){dfs(v,id);low[u]=min(low[u],low[v]);if(low[v]>time[u])out.push_back(id);}else low[u]=min(low[u],time[v]);}};for(int u=0;u<n;u++)if(time[u]<0)dfs(u,-1);sort(out.begin(),out.end());return out;}};